var CHILDREN_OPENNING = 0.875;
var CHILDREN_NUMBER = 10;
var STROKE_WEIGHT = 5;
var STROKE_RATE = 0.2;
var STROKE_DIFF = 1.5;
var BRANCH_CURVATURE = 0.4;
var TOP_CURVATURE = 0.75;
var SIZE_RATE = 0.2;
var SIZE_VARIATION = 0.015;
var ANGLE_VARIATION = 0.05;

var branch;
var seed;
var colors = {};

function setup() {
  createCanvas(windowWidth, windowHeight);

  colors = {
    background: color(62, 98, 88),
    midground: color(23, 57, 44),
    foreground: color(174, 202, 185)
  }

  reSeed();
  createFlowers();

  // noLoop() removed for animation
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  createFlowers();
  redraw();
}

function mousePressed() {
  if (mouseButton === LEFT) {
    reSeed();
    createFlowers();
    redraw();
  }
}

function  keyTyped() {
  if (key == ' ') {
    saveCanvas('fennel_flowers_' + seed + '_' + width + 'x' + height, 'png');
  }
}

function draw() {
  background(colors.background);

  let nTotal = branch.length;
  for(let i = 0; i < nTotal; ++i) {
    branch[i].draw();
  }
}

function reSeed() {
  seed = floor(random(9e15));
}

function createFlowers() {
  randomSeed(seed);
  branch = [];

  // create midground flowers
  let nMG = 10;  
  let gapMG = width/nMG
  for (let i = 0; i < nMG; ++i) {  
    let x = 0.5*gapMG + i*gapMG + random(-0.5, 0.5)*gapMG;
    let y = random(height/2, height);
    let size = random(0.1*width, 0.2*width);
    let angle = radians(random(88, 93));
    branch.push(FennelUtil.createFlowerAt(createVector(x, y),
                                          size,
                                          angle,
                                          colors.midground));
  }

  // create foreground flowers
  let nFG = 5;
  let gapFG = width/nFG;
  for (let i = 0; i < nFG; ++i) {
    let x = 0.5*gapFG + i*gapFG + random(-0.5, 0.5)*gapFG;
    let y = random(height/3, 2*height/3);
    let size = random(0.15*width, 0.35*width);
    let angle = radians(random(88, 93));
    branch.push(FennelUtil.createFlowerAt(createVector(x, y),
                                          size,
                                          angle,
                                          colors.foreground));
  }

}

class Fennel {
    constructor(startPoint, branchLength, curvatureAngle, branchOrientation, fennelColor, strokeWeight, level) {
      this.startPoint = startPoint;
      this.branchLength = branchLength;
      this.curvatureAngle = curvatureAngle;
      this.branchOrientation = branchOrientation;
      this.fennelColor = fennelColor;
      this.level = level;
      this.strokeWeight = strokeWeight;
      this.endPoint = p5.Vector.fromAngle(-this.curvatureAngle).mult(this.branchLength);
      this.ajustPoint = BRANCH_CURVATURE*this.branchLength*cos(this.curvatureAngle);

      this.children = [];
      if (level-- > 0) {
        for (let i = 0; i < CHILDREN_NUMBER; ++ i) {
          let nstart = this.endPoint;
          let nangle = FennelUtil.calcChildAngle(i);
          let nlength = FennelUtil.calcChildLength(nangle, this.branchLength);
          let ntheta = curvatureAngle - HALF_PI;
          let weight = map(nlength, 0, this.branchLength, STROKE_RATE*this.strokeWeight, this.strokeWeight);
          let child = new Fennel(nstart, nlength, nangle, ntheta, fennelColor, weight, level);

          this.children.push(child);
        }
      }
    }

    draw() {
      strokeWeight(this.strokeWeight);

      push();
      translate(this.startPoint.x, this.startPoint.y);
      rotate(-this.branchOrientation);

      stroke(this.fennelColor);
      fill(this.fennelColor);
      beginShape();
      vertex(-STROKE_DIFF*this.strokeWeight, 0);
      bezierVertex(this.ajustPoint, 0,
                   this.endPoint.x, this.endPoint.y,
                   this.endPoint.x, this.endPoint.y);
      bezierVertex(this.endPoint.x, this.endPoint.y,
                   this.ajustPoint, 0,
                   STROKE_DIFF*this.strokeWeight, 0);
      endShape();

      if (this.level) {
        for (let i = 0; i < CHILDREN_NUMBER; ++ i) {
          this.children[i].draw();
        }
      }
      pop();
    }
  }

var FennelUtil = {
  calcChildAngle: function(idx) {
    let angle = map(idx,
                    0, CHILDREN_NUMBER,
                    (1 - CHILDREN_OPENNING)*PI, CHILDREN_OPENNING*PI);

    angle += random(-ANGLE_VARIATION*PI, ANGLE_VARIATION*PI);

    return angle;
  },

  calcChildLength: function(childAngle, parentLength) {
    let length = map(abs(childAngle - HALF_PI),
                     (1 - CHILDREN_OPENNING)*PI, CHILDREN_OPENNING*PI,
                     TOP_CURVATURE*SIZE_RATE*parentLength, SIZE_RATE*parentLength);

    length += random(-SIZE_VARIATION*parentLength, SIZE_VARIATION*parentLength);

    return length;
  },

  createFlowerAt: function(position, size, orientation, color) {
    var length = 3 * size;
    var signal = random(1) > 0.5 ? 1 : -1;
    var angle = radians(random(10, 30)*(signal));
    var level = 3;
    var weight = 0.02*size;
    var start = p5.Vector.fromAngle(PI - angle - orientation).mult(length).add(position);

    var flower = new Fennel(start, length, angle, orientation, color, weight, level);
    return flower;
  }
}
